from format_lecon import Lesson,paras,table,steps
from diagnostics import comparison
from medicaments import antalgie,amoxicilline
l=Lesson('Mal de gorge')
l.add('Le {mal de gorge} est un symptôme, souvent aggravé par la déglutition. La pharyngite atteint la muqueuse pharyngée et l’amygdalite les amygdales. Il faut d’abord repérer une obstruction respiratoire ou une infection profonde.',paras('L’odynophagie désigne la douleur lors de la déglutition ; la dysphagie désigne une difficulté au passage des aliments ou liquides. L’aphagie correspond à l’impossibilité d’avaler. Ces termes ne sont pas interchangeables.', 'Un fond de gorge rouge ne précise ni la cause ni la gravité. Une douleur intense avec un examen buccal peu explicatif peut provenir d’une atteinte située plus bas, notamment supraglottique.'),(3,4,7))
l.add('Les {infections virales sont majoritaires}. L’âge, les contacts et la durée changent les hypothèses. Les causes rares restent prioritaires lorsqu’elles menacent la respiration ou évoquent un sepsis.',paras('Pédiatrie suisse 2023 rapporte que le streptocoque du groupe A représente 5 à 15 % des angines chez l’adulte et 20 à 30 % chez l’enfant. Ce sont des proportions parmi les angines rapportées dans une synthèse, et non des incidences suisses de tous les maux de gorge.', 'Le classement des dix diagnostics est pédagogique : les causes usuelles viennent d’abord, puis des situations discriminantes et graves. Aucune série suisse lue ne permet de classer quantitativement ces dix entités entre elles ; leur rang ne prétend donc pas être un classement mesuré de prévalence.', 'Une angine aiguë non compliquée évolue généralement vers l’amélioration en environ une semaine. Une aggravation, une reprise fébrile ou une persistance inhabituelle impose de réexaminer la cause.'),(1,2,3,6))
an=l.subwindow('anatomie','Pharynx, amygdales, larynx et espaces cervicaux',paras('L’oropharynx est situé derrière la cavité buccale, entre le voile du palais et la région de la base de langue et de l’épiglotte. Il participe à la respiration, à la déglutition et à la défense muqueuse. Les amygdales palatines sont du tissu lymphoïde latéral.', 'Le larynx constitue la voie aérienne ; une inflammation supraglottique peut rétrécir son entrée. Un œdème peut donc gêner la respiration sans produire une volumineuse amygdale visible à l’ouverture de la bouche.', 'Une infection qui dépasse la muqueuse peut former une collection autour de l’amygdale ou dans un espace cervical profond. La proximité de la jugulaire interne et la continuité des espaces profonds expliquent le risque de thrombophlébite septique et d’extension thoracique.'),(3,4,7,11))
l.add('Les {bases anatomiques relient douleur et urgence}. Une inflammation muqueuse n’a pas le même risque qu’une collection cervicale. L’œdème laryngé menace directement la voie aérienne.',paras(an)+table(['Perturbation','Exploration','Réponse thérapeutique'],[['Inflammation de surface.','Examen prudent et tests ciblés selon contexte.','Hydratation et antalgie ; traitement étiologique si indiqué.'],['Collection purulente.','Examen ORL et imagerie selon profondeur et stabilité.','Antibiothérapie et drainage selon le foyer.'],['Œdème supraglottique.','Évaluation respiratoire puis endoscopie sécurisée.','Sécurisation des voies aériennes et traitement hospitalier.'],['Thrombophlébite septique.','Hémocultures et imagerie cervicothoracique.','Traitement du sepsis et contrôle du foyer.']]),(3,4,7,11))
l.add('Le {tri fait passer les urgences avant le score de Centor}. Stridor, détresse respiratoire ou impossibilité d’avaler la salive imposent une prise en charge immédiate. Une infection profonde ou un sepsis ne se traite pas comme une angine simple.',table(['Priorité','Signes','Action'],[['🚩 E1 : voie aérienne.','Stridor, tirage, position penchée en avant, salivation ou cyanose.','Appeler le 144 ; laisser la position de confort, éviter toute exploration forcée ; équipe ORL et anesthésie.'],['🚩 E2 : suppuration profonde.','Trismus, douleur unilatérale, voile bombé, torticolis ou tuméfaction cervicale.','Évaluation ORL urgente, hospitalisation selon gravité ; ne pas retarder pour un test streptococcique.'],['🚩 E3 : sepsis ou toxine.','Altération générale, reprise fébrile avec douleur cervicale, signes pulmonaires ou pseudomembrane adhérente.','Urgence hospitalière ; considérer Lemierre et diphtérie, isolement si suspicion de cette dernière.'],['🚩 E4 : tumeur.','Symptôme unilatéral progressif ou persistant, otalgie réflexe, masse cervicale.','Examen ORL et biopsie si lésion suspecte ; ne pas multiplier les antibiotiques empiriques.']]),(3,4,5,7,10,11))
l.add('L’{anamnèse cherche ce qui change la conduite}. Préciser durée, fièvre, toux, voix, déglutition et latéralité. Demander terrain immunitaire, médicaments, vaccination et expositions pertinentes.',paras('Une reprise de fièvre après une angine avec douleur latérale du cou suggère une complication septique. Une incapacité à boire ou une diurèse réduite signale un risque de déshydratation. Une douleur abdominale brutale dans un syndrome mononucléosique impose de rechercher une complication splénique.', 'Rechercher antécédents personnels ou familiaux de rhumatisme articulaire aigu et contexte épidémiologique individuel. Une origine géographique seule ne pose aucun diagnostic. Interroger sans jugement sur les contacts sexuels oraux si pertinents, ainsi que tabac, alcool, exposition irritante et reflux pour une plainte persistante.'),(2,3,5,7,8,9))
l.add('L’{examen commence par la respiration et l’état général}. Examiner ensuite bouche, pharynx et cou si la situation le permet. Une suspicion d’épiglottite interdit de provoquer une agitation ou un examen forcé.',paras('Observer voix, fréquence et effort respiratoires, salive, position spontanée et hydratation. Mesurer les constantes utiles ; une saturation initialement rassurante n’annule pas les signes cliniques d’obstruction.', 'Chez une personne stable, éclairer la bouche et comparer les deux côtés : rougeur, exsudat, voile, luette, ulcération et ouverture buccale. Palper les aires ganglionnaires et le cou sans manipulation douloureuse excessive. Une otoscopie peut montrer un tympan normal malgré une otalgie réflexe.', 'Selon l’hypothèse, rechercher éruption cutanée, adénopathies hors du cou et hépatosplénomégalie avec prudence. Une inspection buccale normale ne visualise pas toute la région supraglottique ; l’endoscopie relève de l’équipe équipée.'),(3,4,7,9,10))
l.add('Le {tableau différentiel distingue dix situations utiles}. Les rangs de fréquence sont qualitatifs et les priorités d’exclusion sont explicites. Le tableau reste non exhaustif.',comparison()+paras('Une primo-infection VIH, une infection à cytomégalovirus, une syphilis, une candidose, une gingivite ulcéronécrotique, un reflux, une irritation ou un écoulement nasal postérieur peuvent aussi donner une douleur pharyngée. Un angiœdème, une brûlure ou un corps étranger doit être recherché si le contexte le suggère ; leur absence du tableau ne les exclut pas.'),(1,2,3,4,5,7,8,11))
l.add('Le {diagnostic positif doit préciser le niveau de certitude}. Un exsudat n’est pas une preuve de streptocoque. Un test négatif pour ce germe ne rassure pas sur les infections profondes.',paras('Centor attribue un point pour chacun des éléments suivants : absence de toux, exsudat amygdalien, histoire de fièvre ou température supérieure à 38 °C, adénopathie cervicale antérieure sensible. Selon la SSI, un score de zéro à deux ne justifie pas de test ni d’antibiotique dans une forme simple ; à trois ou quatre, envisager le test si son résultat change le traitement.', 'Les recommandations pédiatriques suisses ajoutent le terrain et le suivi : sans critère d’inquiétude, une observation avec réévaluation à 48–72 heures peut être retenue, même devant un tableau évocateur. Les antécédents de rhumatisme articulaire aigu justifient une démarche particulière quel que soit le score. Les scores ne sont ni des preuves étiologiques ni des outils d’exclusion d’une urgence.'),(1,2,3))
l.add('Les {examens complémentaires sont ciblés}. Le frottis streptococcique sert une décision thérapeutique précise. Les tableaux atypiques demandent des examens différents.',table(['Étape','Examen et interprétation'],[['9.a : forme simple.','Pas de bilan sanguin ou d’imagerie systématique ; test rapide si indication clinique selon le parcours suisse.'],['9.b : suspicion mononucléosique ou exposition.','Sérologie EBV selon délai ; bilan hépatique ou hémogramme si utile. Tests VIH et autres infections selon contexte et consentement.'],['9.c : suppuration ou sepsis.','Hémocultures et prélèvements du foyer sans retarder traitement urgent ; imagerie cervicale injectée si stabilité respiratoire.'],['9.d : cible spécifique.','PCR et culture pharyngées pour gonocoque ; recherche spécifique de corynébactérie et de toxigénicité pour diphtérie ; biopsie pour lésion tumorale.']])+paras('La SSI ne recommande pas la culture de contrôle systématique après un test rapide streptococcique négatif dans une forme simple. Cela ne supprime pas les cultures destinées à un abcès, au gonocoque, à la diphtérie ou à un sepsis. Le laboratoire doit connaître la suspicion.'),(1,2,3,5,7,8,11))
l.add('L’{algorithme commence par la gravité}. La décision d’antibiotique vient après l’évaluation clinique. La réévaluation fait partie du traitement.',steps('Si obstruction ou menace respiratoire, appeler le 144 et organiser la sécurisation spécialisée.', 'Si trismus, asymétrie, torticolis, sepsis ou reprise fébrile, rechercher collection profonde ou Lemierre à l’hôpital.', 'Si pseudomembrane et suspicion diphtérique, isoler, contacter l’infectiologue et le médecin cantonal, prélever et traiter sans attendre une confirmation tardive.', 'Si forme simple, apprécier terrain et Centor ; tester seulement si utile, puis choisir observation ou antibiotique selon le parcours suisse.', 'Si syndrome mononucléosique ou exposition sexuelle, demander les tests adaptés et éviter un traitement aveugle.', 'Si persistance, progression ou masse, obtenir un examen ORL plutôt que répéter une prescription empirique.'),(1,2,3,4,5,7,8,11))
aa=antalgie(l);ab=amoxicilline(l)
l.add('La {prise en charge suisse associe soutien et traitement ciblé}. Soulager la douleur et maintenir l’hydratation lorsque la déglutition est sûre. Une antibiothérapie ne devient pas automatique parce qu’un test streptococcique est positif.',paras('<em>11.A — Stabilisation.</em> Une menace respiratoire ou une infection profonde impose une filière hospitalière. Ne pas forcer un traitement oral chez une personne qui n’avale plus.', '<em>11.B — Soutien.</em> Boire régulièrement si possible, adapter l’alimentation et utiliser une antalgie compatible avec le terrain. '+aa, '<em>11.C — Traitement étiologique.</em> L’observation est une option suisse pour l’angine à streptocoque non compliquée, avec consignes et suivi. Si l’antibiothérapie est retenue, distinguer clairement recommandation SSI et information professionnelle. '+ab, '<em>11.D — Suivi.</em> Réévaluer à 48–72 heures selon le parcours pédiatrique suisse, plus tôt en cas d’aggravation. NICE converge sur la prescription sélective mais utilise aussi FeverPAIN et ne recommande pas les tests rapides en routine ; cette organisation britannique n’est pas substituée au parcours suisse. Une grossesse, une immunosuppression ou une difficulté de suivi justifie une adaptation individuelle.'),(1,2,6,12,13))
l.add('La {prévention dépend de la cause}. Hygiène des mains, réduction des contacts avec les sécrétions et vaccination adaptée limitent certains risques. Les règles d’éviction ne sont pas identiques pour toutes les infections.',paras('Pédiatrie suisse 2023 rapporte la suppression de l’éviction scolaire systématique pour l’angine à streptocoque : l’état général guide la fréquentation, sous réserve des consignes sanitaires particulières. Ne pas imposer une règle britannique ou une règle de diphtérie à toutes les angines.', 'Dans la diphtérie, l’isolement et la prise en charge des contacts suivent l’OFSP. Dans la gonococcie, les partenaires et le contrôle microbiologique font partie de la prise en charge. Pour une mononucléose, éviter les activités exposant la rate et réévaluer avant la reprise sportive.'),(2,5,8,9))
l.add('Le {message essentiel est de traiter une situation clinique}. Le score et le test ne remplacent pas le tri. Une plainte persistante ou unilatérale mérite un diagnostic réexaminé.',paras('Les recommandations suisses réduisent les antibiotiques dans les formes simples, tout en maintenant une vigilance forte pour les complications. Une recommandation récente peut différer d’une notice AIPS : le cours rend cette divergence explicite sans transformer une dose ancienne en conduite actuelle.'),(1,2,3,8,12,14))
l.quiz([('Un exsudat amygdalien prouve-t-il une infection à streptocoque ?','Non ; les infections virales peuvent aussi produire un exsudat.'),('Quel ordre prime sur Centor ?','Le tri respiratoire et la recherche de sepsis ou d’infection profonde.'),('Faut-il forcer l’examen de gorge si une épiglottite est suspectée ?','Non ; limiter les manipulations et appeler une équipe équipée.'),('Un test streptococcique négatif exclut-il un abcès ?','Non.'),('Que suggèrent trismus et douleur unilatérale ?','Une complication périamygdalienne ou cervicale profonde.'),('Reprise fébrile et douleur latérale du cou après une angine : quelle urgence ?','Rechercher notamment un syndrome de Lemierre.'),('Le test streptococcique est-il systématique en Suisse ?','Non ; il dépend de la probabilité clinique et de son utilité thérapeutique.'),('Un test positif impose-t-il toujours un antibiotique ?','Non, une observation organisée est une option dans une forme simple.'),('La durée SSI de six jours est-elle celle de la notice Amoxicilline Sandoz citée ?','Non ; cette notice mentionne au moins dix jours pour le streptocoque du groupe A.'),('Quel diagnostic contre-indique cette amoxicilline ?','La mononucléose infectieuse, selon la notice citée.'),('Une hépatite aiguë permet-elle simplement de réduire DAFALGAN ?','Non ; c’est une contre-indication de la notice citée.'),('Pourquoi une culture est-elle utile pour le gonocoque ?','Pour documenter la sensibilité aux antibiotiques, en complément de la PCR.'),('Une suspicion de diphtérie peut-elle attendre tranquillement le laboratoire ?','Non ; isolement, avis spécialisé, déclaration et traitement sont urgents.'),('Une otalgie à tympan normal avec douleur pharyngée persistante est-elle rassurante ?','Non ; une douleur réflexe peut révéler une lésion pharyngée.')],(1,2,3,4,5,7,8,12,13))
l.write()
